import React, { useState } from "react";
import "./Sidebar.scss";

const Sidebar = () => {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <>
      {/* Botão para abrir/fechar o Sidebar */}
      <button
        className="sidebar-toggle"
        onMouseEnter={() => setIsOpen(true)} // Abre o menu quando o mouse entra no botão
        onMouseLeave={() => setIsOpen(false)} // Fecha o menu quando o mouse sai do botão
      >
        {isOpen ? "✖" : "☰"}
      </button>

      {/* Sidebar */}
      <div className={`sidebar ${isOpen ? "open" : ""}`}>
        <ul>
          <li>🔄 DEVOLUÇÃO</li>
          <li>📦 STATUS DO PEDIDO</li>
          <li>❓ PERGUNTAS FREQUENTES</li>
          <li>💬 CHAT</li>
          <li>📲 WHATSAPP</li>
          <li>🛍️ VENDEDOR ONLINE</li>
        </ul>
      </div>
    </>
  );
};

export default Sidebar;
